package com.dsaroadmap.controller;
import com.dsaroadmap.dto.ApiDtos.*;import com.dsaroadmap.service.AuthService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService auth){this.auth=auth;}
@PostMapping("/signup")@ResponseStatus(HttpStatus.CREATED) AuthResponse signup(@Valid @RequestBody SignUpRequest r){return auth.signup(r);}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}@PostMapping("/refresh") AuthResponse refresh(@Valid @RequestBody RefreshRequest r){return auth.refresh(r.refreshToken());}@PostMapping("/logout") MessageResponse logout(@Valid @RequestBody RefreshRequest r){auth.logout(r.refreshToken());return new MessageResponse("Signed out");}@PostMapping("/forgot-password") MessageResponse forgot(@Valid @RequestBody ForgotPasswordRequest r){auth.forgotPassword(r.email());return new MessageResponse("If an account exists, a reset link has been prepared");}@PostMapping("/reset-password") MessageResponse reset(@Valid @RequestBody ResetPasswordRequest r){auth.resetPassword(r);return new MessageResponse("Password updated");}@GetMapping("/me") UserView me(Authentication a){return auth.me(a.getName());}@GetMapping("/oauth-failure")@ResponseStatus(HttpStatus.UNAUTHORIZED) MessageResponse oauthFailure(){return new MessageResponse("Google sign-in failed");}}

